import { AssetService } from '../src/index.js';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import dotenv from 'dotenv';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// 加载环境变量
dotenv.config();

const assetService = new AssetService(
    process.env.OWNER_ID,
    process.env.IS_GROUP === 'true',
    process.env.API_KEY
);

export async function uploadSprite(spritePath, spriteName) {
    try {
        // 测试文件路径
        // const imagePath = path.join(__dirname, spritePath);
        const imagePath = spritePath

        // 确保测试文件存在
        if (!fs.existsSync(imagePath)) {
            console.error('✗ 测试图片文件不存在:', imagePath);
            return;
        }

        // 读取图片文件
        const imageBuffer = fs.readFileSync(imagePath);

        // 上传图片
        const result = await assetService.create("Image", spriteName, imageBuffer, {
            description: '这是一个测试图片',
        });

        try {
            let getResult = undefined;
            while (!getResult || !getResult.response) { // Roblox backend has a race condition. This is a hacky fix.
                await new Promise(r => setTimeout(r, 1000));
                getResult = await assetService.get(result.path);
      
                if (getResult && getResult.error) {
                    throw new Error(getResult.error);
                }
            }
            return getResult.response.assetId;
        } catch (err) {
            console.log("Upload failed:", err);
        }
    } catch (error) {
        console.error('✗ 图片上传失败:', error);
    }
    return -1;
}